#!/usr/bin/env node
// Bundles index.html + styles.css + js/*.js + data/onnx-metadata.js into one
// self-contained file that runs straight from the filesystem (file://).
//
//     node bundle.js            -> ./onnx-operator-atlas.html
//     node bundle.js out.html   -> custom target

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const target = path.resolve(process.argv[2] || path.join(here, 'onnx-operator-atlas.html'));

// A literal `</script` inside an inline script would close the tag early.
const guard = (code) => code.replace(/<\/script/gi, '<\\/script');

const read = (file) => fs.readFileSync(path.join(here, file), 'utf8');

let html = read('index.html');
const assets = [];

html = html.replace(/[ \t]*<link rel="stylesheet" href="([^"]+)">\n?/g, (match, href) => {
    assets.push(href);
    const css = read(href);
    return `<style>\n${css.trimEnd()}\n</style>\n`;
});

html = html.replace(/[ \t]*<script src="([^"]+)"><\/script>\n?/g, (match, src) => {
    assets.push(src);
    const code = read(src);
    const label = src.replace(/[^\w.-]/g, '_');
    return `<script>/* ${src} */\n${guard(code.trimEnd())}\n</script>\n`;
});

const inline = `<script>/* inlined */</script>`;
if (html.includes(inline) || html.includes('src="')) {
    throw new Error('Some assets were not inlined; check the script/link tags in index.html.');
}

const banner = [
    '<!--',
    '  ONNX Operator Atlas - a standalone explorer for source/onnx-metadata.json.',
    '  Generated by bundle.js; edit index.html, styles.css, js/ and re-bundle instead.',
    `  Assets: ${assets.join(', ')}`,
    '-->',
].join('\n');

html = html.replace(/^<!DOCTYPE html>/i, `<!DOCTYPE html>\n${banner}`);

fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(target, html);
console.log(`Wrote ${path.relative(process.cwd(), target)} (${(html.length / 1048576).toFixed(1)} MB)`);
console.log(`  inlined: ${assets.join(', ')}`);
